    "content": "Disclosed a critical Broken Object Level Authorization (BOLA/IDOR) vulnerability in a healthcare API during an authorized penetration test. Changing the user ID parameter in the URL exposed medical records. Always enforce authorization on the server! #infosec #cybersecurity #bugbounty",
